package erratum

import "errors"

// Use opens a resource via opener, calls Frob(input) on it, and closes it
// exactly once in all cases. Transient open errors are retried; other open
// errors are returned. Panics from Frob are recovered: a FrobError triggers
// Defrob with its defrobTag, and the panic value is returned as an error.
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	var err error

	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var transient TransientError
		if !errors.As(err, &transient) {
			return err
		}
	}

	defer func() {
		if r := recover(); r != nil {
			if fe, ok := r.(FrobError); ok {
				resource.Defrob(fe.defrobTag)
			}
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = errors.New("panic")
			}
		}
		resource.Close()
	}()

	resource.Frob(input)
	return nil
}

